/// C: `uint8_t voiceFromModTargValue(uint8_t val)` (`Core/Src/menu/Cc2Text.c:459`).
pub fn voiceFromModTargValue(val: u8) -> u8 {
    let o = &modTargetVoiceOffsets;
    if o[3][0] <= val {
        if o[4][0] <= val {
            if o[5][0] <= val {
                if o[5][1] >= val { 6 } else { 0 }
            } else {
                5
            }
        } else {
            4
        }
    } else if o[0][0] <= val {
        if o[1][0] <= val {
            if o[2][0] <= val { 3 } else { 2 }
        } else {
            1
        }
    } else {
        0
    }
}
